import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { getRooms, getMess } from '../api/listingService';
import { FaUtensils, FaBed, FaSearch, FaFilter, FaMapMarkerAlt, FaStar, FaChevronLeft, FaChevronRight } from 'react-icons/fa';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from '../components/ui/accordion';
import Footer from '../components/common/Footer';

const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

const getCachedData = (key) => {
    try {
        const cached = sessionStorage.getItem(key);
        if (!cached) return null;

        const { data, timestamp } = JSON.parse(cached);
        if (Date.now() - timestamp < CACHE_DURATION) {
            return data;
        }
        return null;
    } catch {
        return null;
    }
};

const setCachedData = (key, data) => {
    try {
        sessionStorage.setItem(key, JSON.stringify({ data, timestamp: Date.now() }));
    } catch {
        // Ignore storage errors
    }
};

const HomePage = () => {
    const [rooms, setRooms] = useState([]);
    const [messServices, setMessServices] = useState([]);
    const [loading, setLoading] = useState(true);
    const [initialLoad, setInitialLoad] = useState(false);
    const [error, setError] = useState(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [showFilters, setShowFilters] = useState(false);
    const [searchType, setSearchType] = useState('rooms');
    const [listingType, setListingType] = useState('all');
    const [roomFilters, setRoomFilters] = useState({
        roomType: '',
        gender: ''
    });
    const [messFilters, setMessFilters] = useState({
        messType: '',
        mealFrequency: ''
    });
    const roomsRef = useRef(null);
    const messRef = useRef(null);
    const navigate = useNavigate();

    // Fetch listings with caching
    useEffect(() => {
        const fetchListings = async () => {
            try {
                // Check cache first for initial load
                const cachedRooms = getCachedData('homepage_rooms');
                const cachedMess = getCachedData('homepage_mess');

                if (cachedRooms) {
                    setRooms(cachedRooms);
                    setInitialLoad(false);
                }
                if (cachedMess) {
                    setMessServices(cachedMess);
                }

                // Only show loading spinner if no cache
                if (!cachedRooms || !cachedMess) {
                    setLoading(true);
                }

                const results = await Promise.allSettled([
                    getRooms(),
                    getMess()
                ]);

                if (results[0].status === 'fulfilled') {
                    const roomsData = results[0].value || [];
                    setRooms(roomsData);
                    setCachedData('homepage_rooms', roomsData);
                } else {
                    console.error("Error fetching rooms:", results[0].reason);
                }

                if (results[1].status === 'fulfilled') {
                    const messData = results[1].value || [];
                    setMessServices(messData);
                    setCachedData('homepage_mess', messData);
                } else {
                    console.error("Error fetching mess services:", results[1].reason);
                }

            } catch (err) {
                setError('Failed to fetch listings. Please try again later.');
                console.error(err);
            } finally {
                setLoading(false);
                setInitialLoad(false);
            }
        };

        fetchListings();
    }, []);

    // Handle search
    const handleSearch = () => {
        const params = new URLSearchParams();
        if (searchQuery.trim()) {
            params.set('searchQuery', searchQuery.trim());
        }

        if (searchType === 'mess') {
            if (messFilters.messType) params.set('messType', messFilters.messType);
            if (messFilters.mealFrequency) params.set('mealFrequency', messFilters.mealFrequency);
            navigate(`/mess?${params.toString()}`);
        } else {
            if (roomFilters.roomType) params.set('roomType', roomFilters.roomType);
            if (roomFilters.gender) params.set('gender', roomFilters.gender);
            navigate(`/rooms?${params.toString()}`);
        }
    };

    const handleRoomTypeChange = (value) => {
        setRoomFilters(prev => ({ ...prev, roomType: value }));
    };

    const handleGenderChange = (value) => {
        setRoomFilters(prev => ({ ...prev, gender: value }));
    };

    const handleMessTypeChange = (value) => {
        setMessFilters(prev => ({ ...prev, messType: value }));
    };

    const handleMealFrequencyChange = (value) => {
        setMessFilters(prev => ({ ...prev, mealFrequency: value }));
    };

    const handleListingTypeChange = (type) => {
        setListingType(type);
        if (type === 'room') {
            setMessFilters({ messType: '', mealFrequency: '' });
        } else if (type === 'mess') {
            setRoomFilters({ roomType: '', gender: '' });
        }
    };

    const clearFilters = () => {
        setSearchQuery('');
        setListingType('all');
        setRoomFilters({ roomType: '', gender: '' });
        setMessFilters({ messType: '', mealFrequency: '' });
        setShowFilters(false);
    };

    const totalListings = rooms.length + messServices.length;
    const availableRooms = rooms.filter(room => room.is_available !== false && room.is_available !== 'false' && room.availability !== false && room.availability !== 'false').length;
    const messCount = messServices.filter(mess => mess.is_available !== false && mess.is_available !== 'false' && mess.availability !== false && mess.availability !== 'false').length;

    // Skeleton components for loading state
    const RoomCardSkeleton = () => (
        <div className="flex-shrink-0 w-72 bg-white rounded-2xl overflow-hidden shadow-lg">
            <div className="h-48 bg-gray-200 animate-pulse" />
            <div className="p-5 space-y-3">
                <div className="h-6 bg-gray-200 rounded animate-pulse w-3/4" />
                <div className="h-4 bg-gray-200 rounded animate-pulse w-1/2" />
                <div className="flex gap-2">
                    <div className="h-6 bg-gray-200 rounded animate-pulse w-16" />
                    <div className="h-6 bg-gray-200 rounded animate-pulse w-16" />
                </div>
            </div>
        </div>
    );

    const SectionSkeleton = ({ title }) => (
        <section className="bg-gradient-to-b from-[#DCC8A8] to-white py-8 sm:py-10">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="text-center mb-12">
                    <div className="h-10 bg-gray-200 rounded animate-pulse w-64 mx-auto mb-4" />
                    <div className="h-5 bg-gray-200 rounded animate-pulse w-96 mx-auto" />
                </div>
                <div className="flex overflow-x-auto space-x-6 pb-4">
                    <RoomCardSkeleton />
                    <RoomCardSkeleton />
                    <RoomCardSkeleton />
                </div>
            </div>
        </section>
    );

    if (initialLoad && loading) {
        return (
            <div className="min-h-screen bg-white overflow-x-hidden font-sans">
                {/* Hero Section Skeleton */}
                <div className="relative pt-12 pb-24 lg:pt-20 lg:pb-32" style={{ background: 'linear-gradient(to bottom right, hsla(147, 39%, 45%, 1.00), hsl(168 59% 14%))' }}>
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
                            <div className="space-y-6 lg:space-y-8">
                                <div className="h-16 bg-white/10 rounded animate-pulse w-3/4" />
                                <div className="h-6 bg-white/10 rounded animate-pulse w-full" />
                                <div className="h-6 bg-white/10 rounded animate-pulse w-2/3" />
                                <div className="bg-green-50 rounded-2xl p-5 shadow-2xl space-y-4">
                                    <div className="flex gap-2">
                                        <div className="h-10 bg-gray-200 rounded-lg flex-1 animate-pulse" />
                                        <div className="h-10 bg-gray-200 rounded-lg flex-1 animate-pulse" />
                                    </div>
                                    <div className="h-10 bg-gray-200 rounded-lg animate-pulse" />
                                </div>
                            </div>
                            <div className="hidden lg:flex justify-center">
                                <div className="w-72 h-72 sm:w-80 sm:h-80 md:w-96 md:h-96 bg-white/10 rounded-3xl animate-pulse" />
                            </div>
                        </div>
                    </div>
                </div>
                <SectionSkeleton />
                <SectionSkeleton />
            </div>
        );
    }

    if (error) return (
        <div className="min-h-screen flex items-center justify-center">
            <div className="text-center p-8">
                <div className="text-red-500 text-6xl mb-4">⚠️</div>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">Error Loading Listings</h2>
                <p className="text-gray-600 mb-6">{error}</p>
                <Button
                    onClick={() => window.location.reload()}
                    className="bg-[#5D8C68] hover:bg-[#4A6F57]"
                >
                    Retry
                </Button>
            </div>
        </div>
    );

    return (
        <div className="min-h-screen bg-white overflow-x-hidden font-sans">

            {/* HERO SECTION */}
            <motion.section
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.3 }}
                className="relative pt-12 pb-24 lg:pt-20 lg:pb-32 overflow-hidden"
                style={{
                    background: 'linear-gradient(to bottom right, hsla(147, 39%, 45%, 1.00), hsl(168 59% 14%))'
                }}
            >
                {/* Decorative Elements */}
                <div className="absolute top-20 left-10 w-32 h-32 bg-white/10 rounded-full blur-2xl"></div>
                <div className="absolute bottom-20 right-20 w-48 h-48 bg-white/5 rounded-full blur-3xl"></div>

                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full relative z-10">
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">

                        {/* LEFT COLUMN: Text, Search Bar, Quick Stats */}
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ duration: 0.4, delay: 0.1 }}
                            className="space-y-6 lg:space-y-8"
                        >
                            {/* Heading & Description */}
                            <div>
                                <h1 className="text-4xl sm:text-5xl lg:text-6xl font-bold leading-tight text-white mb-4">
                                    Your Home Away <span className="text-yellow-300">From Home</span>
                                </h1>
                                <p className="text-lg md:text-xl text-white/90 max-w-xl leading-relaxed">
                                    Focus on your studies, leave the "living" part to us.
                                    Find verified PGs, Hostels, and Daily Tiffin services near your campus.
                                </p>
                            </div>

                            {/* SEARCH BAR CARD (Moved to Left) */}
                            <div className="bg-green-50 rounded-2xl p-5 shadow-2xl">
                                <div className="mb-3">
                                    <label className="block text-xs font-bold text-gray-600 mb-2 uppercase tracking-wide">
                                        What are you looking for?
                                    </label>
                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => setSearchType("rooms")}
                                            className={`flex-1 py-2 rounded-lg font-medium transition-colors text-sm ${searchType === "rooms"
                                                ? "bg-[#4A6F57] text-white"
                                                : "bg-green-100 text-gray-700 hover:bg-green-200"
                                                }`}
                                        >
                                            <FaBed className="inline mr-1" /> Rooms
                                        </button>
                                        <button
                                            onClick={() => setSearchType("mess")}
                                            className={`flex-1 py-2 rounded-lg font-medium transition-colors text-sm ${searchType === "mess"
                                                ? "bg-green-600 text-white"
                                                : "bg-green-100 text-gray-700 hover:bg-green-200"
                                                }`}
                                        >
                                            <FaUtensils className="inline mr-1" /> Tiffin
                                        </button>
                                    </div>
                                </div>

                                <div className="relative mb-3">
                                    <FaSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500" />
                                    <Input
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                                        placeholder="Search by location, amenities..."
                                        className="w-full pl-9 pr-4 py-2 bg-green-100 border border-gray-200 rounded-lg text-gray-800 text-sm focus:ring-[#4A6F57]"
                                    />
                                </div>

                                {/* Filters Button */}
                                <Button
                                    type="button"
                                    variant="ghost"
                                    onClick={() => setShowFilters(!showFilters)}
                                    className="w-full flex items-center justify-between text-gray-600 hover:text-[#4A6F57] py-1 mb-2 px-0 h-auto text-xs"
                                >
                                    <span className="font-medium">Advanced Filters</span>
                                    <FaFilter />
                                </Button>

                                {/* Filters Dropdown */}
                                {showFilters && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: "auto", opacity: 1 }}
                                        className="bg-green-50 rounded-lg p-2 mb-3 border border-green-100 text-xs"
                                    >
                                        <div className="flex flex-wrap gap-2">
                                            <Select
                                                value={listingType}
                                                onValueChange={handleListingTypeChange}
                                            >
                                                <SelectTrigger className="flex-1 h-8 text-xs">
                                                    <SelectValue placeholder="All" />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="all">All</SelectItem>
                                                    <SelectItem value="room">Rooms</SelectItem>
                                                    <SelectItem value="mess">Mess</SelectItem>
                                                </SelectContent>
                                            </Select>

                                            {listingType === "room" && (
                                                <>
                                                    <Select
                                                        value={roomFilters.roomType}
                                                        onValueChange={handleRoomTypeChange}
                                                    >
                                                        <SelectTrigger className="flex-1 h-8 text-xs">
                                                            <SelectValue placeholder="Room Type" />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="single">Single</SelectItem>
                                                            <SelectItem value="double">Double</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                    <Select
                                                        value={roomFilters.gender}
                                                        onValueChange={handleGenderChange}
                                                    >
                                                        <SelectTrigger className="flex-1 h-8 text-xs">
                                                            <SelectValue placeholder="Gender" />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="boys">Boys</SelectItem>
                                                            <SelectItem value="girls">Girls</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                </>
                                            )}

                                            {listingType === "mess" && (
                                                <>
                                                    <Select
                                                        value={messFilters.messType}
                                                        onValueChange={handleMessTypeChange}
                                                    >
                                                        <SelectTrigger className="flex-1 h-8 text-xs">
                                                            <SelectValue placeholder="Type" />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="veg">Veg</SelectItem>
                                                            <SelectItem value="nonveg">Non-Veg</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                    <Select
                                                        value={messFilters.mealFrequency}
                                                        onValueChange={handleMealFrequencyChange}
                                                    >
                                                        <SelectTrigger className="flex-1 h-8 text-xs">
                                                            <SelectValue placeholder="Freq" />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="once">Once</SelectItem>
                                                            <SelectItem value="twice">Twice</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                </>
                                            )}
                                        </div>
                                        <Button
                                            variant="link"
                                            onClick={clearFilters}
                                            className="text-red-500 text-[10px] font-semibold p-0 h-auto mt-1"
                                        >
                                            Clear Filters
                                        </Button>
                                    </motion.div>
                                )}

                                {/* Search Now Button */}
                                <Button
                                    onClick={handleSearch}
                                    className={`w-full py-2 font-bold rounded-lg shadow-md hover:shadow-lg transition-all text-sm ${searchType === "mess"
                                        ? "bg-green-600 hover:bg-green-700"
                                        : "bg-[#4A6F57] hover:bg-[#3A5B45]"
                                        } text-white`}
                                >
                                    Search Now
                                </Button>
                            </div>

                            {/* QUICK STATS (Below Search) */}
                            <div className="flex flex-wrap gap-4 pt-2">
                                <div className="bg-white/20 backdrop-blur-sm rounded-lg px-4 py-2 border border-white/20 flex items-center">
                                    <span className="font-bold text-lg text-white mr-2">{totalListings}+</span>
                                    <span className="text-xs opacity-90 text-white">Listings</span>
                                </div>
                                <div className="bg-white/20 backdrop-blur-sm rounded-lg px-4 py-2 border border-white/20 flex items-center">
                                    <span className="font-bold text-lg text-white mr-2">{availableRooms}+</span>
                                    <span className="text-xs opacity-90 text-white">Rooms</span>
                                </div>
                                <div className="bg-white/20 backdrop-blur-sm rounded-lg px-4 py-2 border border-white/20 flex items-center">
                                    <span className="font-bold text-lg text-white mr-2">{messCount}+</span>
                                    <span className="text-xs opacity-90 text-white">Available Messes</span>
                                </div>
                            </div>
                        </motion.div>

                        {/* RIGHT COLUMN: Image (Restored Original Visual) */}
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            transition={{ duration: 0.4, delay: 0.2 }}
                            className="relative z-10 flex justify-center lg:justify-end"
                        >
                            <div className="relative w-72 h-72 sm:w-80 sm:h-80 md:w-96 md:h-96">
                                {/* Main Window - Image Background */}
                                <div className="absolute inset-0 bg-gradient-to-br from-white/20 to-white/5 backdrop-blur-md rounded-3xl border-2 border-white/30 shadow-2xl overflow-hidden">
                                    <img
                                        src="/homepage_logo.png"
                                        alt="Student Accommodation"
                                        className="w-full h-full object-cover"
                                        onError={(e) => { e.target.style.display = 'none'; }}
                                    />
                                </div>

                                {/* Decorative Elements - Lighter animations */}
                                <motion.div
                                    animate={{ rotate: 360 }}
                                    transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
                                    className="absolute -top-8 -left-8 text-yellow-300 text-6xl sm:text-7xl"
                                >
                                    ✦
                                </motion.div>
                                <motion.div
                                    animate={{ y: [0, -8, 0] }}
                                    transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
                                    className="absolute top-12 -left-10 text-yellow-300 text-4xl sm:text-5xl"
                                >
                                    ✦
                                </motion.div>
                                <motion.div
                                    animate={{ y: [0, 8, 0] }}
                                    transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
                                    className="absolute -bottom-10 -right-10 text-yellow-300 text-6xl sm:text-7xl"
                                >
                                    ✦
                                </motion.div>
                            </div>
                        </motion.div>
                    </div>
                </div>

                {/* IMPROVED WAVE DIVIDER (3 Layers) */}
                <div className="absolute bottom-0 left-0 right-0 w-full overflow-hidden leading-none">
                    <svg className="relative block w-full h-20 md:h-24 lg:h-32" viewBox="0 0 1440 320" preserveAspectRatio="none">
                        <path fill="#DCC8A8" fillOpacity="0.4" d="M0,192L48,197.3C96,203,192,213,288,229.3C384,245,480,267,576,250.7C672,235,768,181,864,181.3C960,181,1056,224,1152,224C1248,224,1344,181,1392,160L1440,139.3L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"></path>
                        <path fill="#DCC8A8" fillOpacity="0.7" d="M0,64L48,80C96,96,192,128,288,128C384,128,480,96,576,90.7C672,85,768,107,864,133.3C960,160,1056,192,1152,186.7C1248,181,1344,139,1392,117.3L1440,96L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"></path>
                        <path fill="#DCC8A8" fillOpacity="1" d="M0,224L48,213.3C96,203,192,181,288,181.3C384,181,480,203,576,224C672,245,768,267,864,250.7C960,235,1056,181,1152,160C1248,139,1344,149,1392,154.7L1440,160L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"></path>
                    </svg>
                </div>
            </motion.section>

            {/* Featured Rooms Section */}
            <section className="bg-gradient-to-b from-[#DCC8A8] to-white py-8 sm:py-10">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.6 }}
                        className="text-center mb-12"
                    >
                        <h2 className="text-3xl sm:text-4xl font-bold text-gray-800 mb-4">
                            Featured <span className="text-[#5D8C68]">Rooms</span>
                        </h2>
                        <p className="text-gray-600 max-w-2xl mx-auto">
                            Find your perfect accommodation with verified listings and transparent pricing
                        </p>
                    </motion.div>

                    {rooms.length > 0 ? (
                        <div className="relative">
                            {/* Scroll buttons */}
                            <div className="absolute -top-4 right-0 flex space-x-2 z-10">
                                <button
                                    onClick={() => {
                                        const container = roomsRef.current;
                                        if (container) {
                                            container.scrollBy({ left: -300, behavior: 'smooth' });
                                        }
                                    }}
                                    className="bg-[#5D8C68] hover:bg-[#4A6F57] text-white rounded-full p-2 shadow-lg transition-all"
                                    aria-label="Scroll left"
                                >
                                    <FaChevronLeft />
                                </button>
                                <button
                                    onClick={() => {
                                        const container = roomsRef.current;
                                        if (container) {
                                            container.scrollBy({ left: 300, behavior: 'smooth' });
                                        }
                                    }}
                                    className="bg-[#5D8C68] hover:bg-[#4A6F57] text-white rounded-full p-2 shadow-lg transition-all"
                                    aria-label="Scroll right"
                                >
                                    <FaChevronRight />
                                </button>
                            </div>
                            {/* Horizontal scroll container */}
                            <div
                                ref={roomsRef}
                                className="mt-6 flex overflow-x-auto space-x-6 pb-4 hide-scrollbar"
                                style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
                            >
                                {rooms.slice(0, 6).map((room, index) => (
                                    <motion.div
                                        key={room.id || index}
                                        initial={{ opacity: 0, y: 20 }}
                                        whileInView={{ opacity: 1, y: 0 }}
                                        viewport={{ once: true }}
                                        transition={{ duration: 0.5, delay: index * 0.1 }}
                                        className="flex-shrink-0 w-72 min-w-0 bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-300 group cursor-pointer"
                                        onClick={() => (room.room_id || room.id) && navigate(`/rooms/${room.room_id || room.id}`)}
                                    >
                                        <div className="relative h-48 overflow-hidden">
                                            {room.cover_photo_url ? (
                                                <img
                                                    src={room.cover_photo_url}
                                                    alt={room.title || "Room"}
                                                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                                                    loading="lazy"
                                                    onError={(e) => { e.target.src = '/images/room-placeholder.jpg'; }}
                                                />
                                            ) : (
                                                <div className="w-full h-full bg-gradient-to-br from-gray-200 to-gray-300 flex items-center justify-center">
                                                    <FaBed className="text-4xl text-gray-400" />
                                                </div>
                                            )}
                                            {/* Availability Badge - handle both boolean and string false */}
                                            {(() => {
                                                const isBooked = room.is_available === false || room.is_available === 'false' ||
                                                    room.availability === false || room.availability === 'false';
                                                return (
                                                    <div className={`absolute top-3 left-3 text-white text-xs font-bold px-3 py-1 rounded-full flex-shrink-0 ${isBooked ? 'bg-red-600' : 'bg-[#5D8C68]'}`}>
                                                        {isBooked ? 'Unavailable' : 'Available'}
                                                    </div>
                                                );
                                            })()}
                                            <div className="absolute bottom-3 right-3 bg-black/70 text-white text-lg font-bold px-3 py-1 rounded-lg flex-shrink-0">
                                                ₹{room.rent || 'N/A'}/mo
                                            </div>
                                        </div>

                                        <div className="p-5 overflow-hidden">
                                            <div className="flex justify-between items-start mb-2 gap-2">
                                                <h3 className="text-lg font-bold text-gray-800 line-clamp-1 flex-1">
                                                    {room.title || 'Room'}
                                                </h3>
                                                {room.rating && (
                                                    <div className="flex items-center gap-1 bg-green-900/80 text-white text-xs font-bold px-2 py-1 rounded flex-shrink-0">
                                                        <FaStar className="w-3 h-3" />
                                                        {parseFloat(room.rating).toFixed(1)}
                                                    </div>
                                                )}
                                            </div>
                                            <div className="flex items-center text-gray-600 mb-3">
                                                <FaMapMarkerAlt className="text-sm mr-1 flex-shrink-0" />
                                                <span className="text-sm truncate">
                                                    {typeof room.location === 'string' ? room.location :
                                                        room.location?.address || room.location?.name ||
                                                        room.address || 'Location not specified'}
                                                </span>
                                            </div>
                                            <div className="flex flex-wrap gap-2 mb-4 overflow-hidden">
                                                {room.accommodation_type && (
                                                    <span className="text-xs bg-gray-100 text-gray-700 px-2 py-1 rounded whitespace-nowrap">
                                                        {room.accommodation_type}
                                                    </span>
                                                )}
                                                {room.gender_preference && (
                                                    <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded whitespace-nowrap">
                                                        {room.gender_preference}
                                                    </span>
                                                )}
                                                {room.sharing_type && (
                                                    <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded whitespace-nowrap">
                                                        {room.sharing_type}
                                                    </span>
                                                )}
                                                {room.has_ac && (
                                                    <span className="text-xs bg-purple-100 text-purple-700 px-2 py-1 rounded whitespace-nowrap">
                                                        AC
                                                    </span>
                                                )}
                                            </div>
                                            <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                                                {room.rating ? (
                                                    <div className="flex items-center">
                                                        <FaStar className="text-yellow-400 mr-1" />
                                                        <span className="font-medium">{parseFloat(room.rating).toFixed(1)}</span>
                                                    </div>
                                                ) : (
                                                    <div className="text-gray-400 text-sm">No ratings</div>
                                                )}
                                                <Button
                                                    size="sm"
                                                    className="bg-[#5D8C68] hover:bg-[#4A6F57] text-white"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        const roomId = room.room_id || room.id;
                                                        if (roomId) {
                                                            navigate(`/rooms/${roomId}`);
                                                        }
                                                    }}
                                                >
                                                    View Details
                                                </Button>
                                            </div>
                                        </div>
                                    </motion.div>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="text-center py-12"
                        >
                            <FaBed className="text-6xl text-gray-300 mx-auto mb-4" />
                            <h3 className="text-xl font-semibold text-gray-600 mb-2">No rooms found</h3>
                            <p className="text-gray-500 mb-6">
                                {searchQuery ? 'Try a different search term' : 'No rooms available at the moment'}
                            </p>
                            {searchQuery && (
                                <Button onClick={clearFilters}>
                                    Clear Search
                                </Button>
                            )}
                        </motion.div>
                    )}

                    {rooms.length > 0 && (
                        <motion.div
                            initial={{ opacity: 0 }}
                            whileInView={{ opacity: 1 }}
                            viewport={{ once: true }}
                            className="text-center mt-10"
                        >
                            <Button
                                variant="outline"
                                className="border-[#5D8C68] text-[#5D8C68] hover:bg-[#5D8C68] hover:text-white px-8 py-3 rounded-xl"
                                onClick={() => navigate('/rooms')}
                            >
                                View All Rooms ({rooms.length})
                            </Button>
                        </motion.div>
                    )}
                </div>
            </section>

            {/* Mess Services Section */}
            <section className="bg-gradient-to-b from-white to-[#DCC8A8] py-8 sm:py-10">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.6 }}
                        className="text-center mb-12"
                    >
                        <h2 className="text-3xl sm:text-4xl font-bold text-gray-800 mb-4">
                            Featured <span className="text-[#5D8C68]">Mess Services</span>
                        </h2>
                        <p className="text-gray-600 max-w-2xl mx-auto">
                            Discover quality food services with affordable pricing and excellent reviews
                        </p>
                    </motion.div>

                    {messServices.length > 0 ? (
                        <div className="relative">
                            {/* Scroll buttons */}
                            <div className="absolute -top-4 right-0 flex space-x-2 z-10">
                                <button
                                    onClick={() => {
                                        const container = messRef.current;
                                        if (container) {
                                            container.scrollBy({ left: -300, behavior: 'smooth' });
                                        }
                                    }}
                                    className="bg-[#5D8C68] hover:bg-[#4A6F57] text-white rounded-full p-2 shadow-lg transition-all"
                                    aria-label="Scroll left"
                                >
                                    <FaChevronLeft />
                                </button>
                                <button
                                    onClick={() => {
                                        const container = messRef.current;
                                        if (container) {
                                            container.scrollBy({ left: 300, behavior: 'smooth' });
                                        }
                                    }}
                                    className="bg-[#5D8C68] hover:bg-[#4A6F57] text-white rounded-full p-2 shadow-lg transition-all"
                                    aria-label="Scroll right"
                                >
                                    <FaChevronRight />
                                </button>
                            </div>
                            {/* Horizontal scroll container */}
                            <div
                                ref={messRef}
                                className="flex overflow-x-auto space-x-6 pb-4 hide-scrollbar"
                                style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
                            >
                                {messServices.slice(0, 6).map((mess, index) => (
                                    <motion.div
                                        key={mess.id || index}
                                        initial={{ opacity: 0, y: 20 }}
                                        whileInView={{ opacity: 1, y: 0 }}
                                        viewport={{ once: true }}
                                        transition={{ duration: 0.5, delay: index * 0.1 }}
                                        className="flex-shrink-0 w-72 min-w-0 bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-300 group cursor-pointer"
                                        onClick={() => (mess.mess_id || mess.id) && navigate(`/mess/${mess.mess_id || mess.id}`)}
                                    >
                                        <div className="relative h-48 overflow-hidden">
                                            {mess.cover_photo_url ? (
                                                <img
                                                    src={mess.cover_photo_url}
                                                    alt={mess.name || "Mess"}
                                                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                                                    loading="lazy"
                                                    onError={(e) => { e.target.src = '/images/mess-placeholder.jpg'; }}
                                                />
                                            ) : (
                                                <div className="w-full h-full bg-gradient-to-br from-orange-200 to-red-200 flex items-center justify-center">
                                                    <FaUtensils className="text-4xl text-gray-400" />
                                                </div>
                                            )}
                                            <div className="absolute top-3 left-3 bg-[#5D8C68] text-white text-xs font-bold px-3 py-1 rounded-full">
                                                {mess.status === 'approved' ? 'Verified' : mess.status || 'Active'}
                                            </div>
                                            <div className="absolute bottom-3 right-3 bg-black/70 text-white text-lg font-bold px-3 py-1 rounded-lg">
                                                ₹{mess.pricing?.monthlyTwoTime?.fullTiffin || mess.pricing?.monthlyTiffin || mess.rent || 'N/A'}/mo
                                            </div>
                                        </div>

                                        <div className="p-5 overflow-hidden">
                                            <h3 className="text-lg font-bold text-gray-800 mb-2 line-clamp-1">
                                                {mess.name || 'Mess Service'}
                                            </h3>
                                            <div className="flex items-center text-gray-600 mb-3">
                                                <FaMapMarkerAlt className="text-sm mr-1 flex-shrink-0" />
                                                <span className="text-sm truncate">
                                                    {typeof mess.location === 'string' ? mess.location :
                                                        mess.location?.address || mess.location?.name ||
                                                        mess.address || 'Location not specified'}
                                                </span>
                                            </div>

                                            <div className="flex flex-wrap gap-2 mb-4 overflow-hidden">
                                                {mess.menu?.type && (
                                                    <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded whitespace-nowrap">
                                                        {mess.menu.type}
                                                    </span>
                                                )}
                                                {mess.service_type && (
                                                    <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded whitespace-nowrap">
                                                        {mess.service_type}
                                                    </span>
                                                )}
                                                {mess.max_capacity && (
                                                    <span className="text-xs bg-purple-100 text-purple-700 px-2 py-1 rounded whitespace-nowrap">
                                                        {mess.max_capacity} seats
                                                    </span>
                                                )}
                                            </div>

                                            <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                                                {mess.rating ? (
                                                    <div className="flex items-center">
                                                        <FaStar className="text-yellow-400 mr-1" />
                                                        <span className="font-medium">{parseFloat(mess.rating).toFixed(1)}</span>
                                                    </div>
                                                ) : (
                                                    <div className="text-gray-400 text-sm">No ratings</div>
                                                )}
                                                <Button
                                                    size="sm"
                                                    className="bg-[#5D8C68] hover:bg-[#4A6F57] text-white"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        const messId = mess.mess_id || mess.id;
                                                        if (messId) {
                                                            navigate(`/mess/${messId}`);
                                                        }
                                                    }}
                                                >
                                                    View Details
                                                </Button>
                                            </div>
                                        </div>
                                    </motion.div>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="text-center py-12"
                        >
                            <FaUtensils className="text-6xl text-gray-300 mx-auto mb-4" />
                            <h3 className="text-xl font-semibold text-gray-600 mb-2">No mess services found</h3>
                            <p className="text-gray-500 mb-6">
                                {searchQuery ? 'Try a different search term' : 'No mess services available at the moment'}
                            </p>
                            {searchQuery && (
                                <Button onClick={clearFilters}>
                                    Clear Search
                                </Button>
                            )}
                        </motion.div>
                    )
                    }

                    {
                        messServices.length > 0 && (
                            <motion.div
                                initial={{ opacity: 0 }}
                                whileInView={{ opacity: 1 }}
                                viewport={{ once: true }}
                                className="text-center mt-10"
                            >
                                <Button
                                    variant="outline"
                                    className="border-[#5D8C68] text-[#5D8C68] hover:bg-[#5D8C68] hover:text-white px-8 py-3 rounded-xl"
                                    onClick={() => navigate('/mess')}
                                >
                                    View All Mess Services ({messServices.length})
                                </Button>
                            </motion.div>
                        )
                    }
                </div>
            </section>

            {/* FAQ Section */}
            <section className="bg-gray-50 py-16">
                <div className="max-w-3xl mx-auto px-4">
                    <div className="text-center mb-12">
                        <h2 className="text-3xl font-bold text-gray-800 mb-4">Frequently Asked Questions</h2>
                        <p className="text-gray-600">Got questions? We've got answers.</p>
                    </div>
                    <Accordion type="single" collapsible className="w-full">
                        <AccordionItem value="item-1">
                            <AccordionTrigger>How do I book a room?</AccordionTrigger>
                            <AccordionContent>
                                Browse listings, select a room you like, and click "Request Booking". The owner will review your request within 24 hours.
                            </AccordionContent>
                        </AccordionItem>
                        <AccordionItem value="item-2">
                            <AccordionTrigger>Is the deposit refundable?</AccordionTrigger>
                            <AccordionContent>
                                Yes, security deposits are typically refundable at the end of your stay, subject to the property's terms and conditions.
                            </AccordionContent>
                        </AccordionItem>
                        <AccordionItem value="item-3">
                            <AccordionTrigger>Can I cancel my tiffin service?</AccordionTrigger>
                            <AccordionContent>
                                Yes, you can cancel or pause your tiffin service. Cancellation policies vary by provider, so please check the specific listing details.
                            </AccordionContent>
                        </AccordionItem>
                        <AccordionItem value="item-5">
                            <AccordionTrigger>How do list ratings work?</AccordionTrigger>
                            <AccordionContent>
                                Ratings are based on user reviews and feedback. Each listing displays an average rating from 1-5 stars, helping you make informed decisions.
                            </AccordionContent>
                        </AccordionItem>
                        <AccordionItem value="item-7">
                            <AccordionTrigger>How can I list my property?</AccordionTrigger>
                            <AccordionContent>
                                Click on "List Your Property" in the navigation menu, fill in the details, upload photos, and submit for verification. Once approved, your listing will go live.
                            </AccordionContent>
                        </AccordionItem>
                        <AccordionItem value="item-8">
                            <AccordionTrigger>How do I contact the owner?</AccordionTrigger>
                            <AccordionContent>
                                Once you find a listing you're interested in, click the "View Details" button and use the "Contact Owner" form to send a message directly.
                            </AccordionContent>
                        </AccordionItem>
                        <AccordionItem value="item-10">
                            <AccordionTrigger>What is your cancellation policy?</AccordionTrigger>
                            <AccordionContent>
                                Cancellation policies are set by individual property owners. Please review the specific terms on each listing before booking.
                            </AccordionContent>
                        </AccordionItem>
                    </Accordion>
                </div>
            </section>

            <Footer />
        </div>
    );
};

export default HomePage;